import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel that fuses scaling, masked_fill, and ReLU
fused_masked_fill_scale_relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>

__global__ void fused_masked_fill_scale_relu_kernel(
    const float* __restrict__ att,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int total_elems,
    float scale,
    int T,
    float negative_infinity
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elems) {
        float val = att[idx] * scale;
        int bias_idx = idx % (T * T);
        if (bias[bias_idx] == 0.0f) {
            val = negative_infinity;
        }
        if (val < 0.0f) {
            val = 0.0f;
        }
        output[idx] = val;
    }
}

torch::Tensor fused_masked_fill_scale_relu_cuda(
    torch::Tensor att,
    torch::Tensor bias,
    float scale,
    int T
) {
    auto output = torch::empty_like(att);
    int total_elems = att.numel();
    float negative_infinity = -1e30f;

    const int blockSize = 256;
    const int gridSize = (total_elems + blockSize - 1) / blockSize;

    fused_masked_fill_scale_relu_kernel<<<gridSize, blockSize>>>(
        att.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        total_elems,
        scale,
        T,
        negative_infinity
    );

    return output;
}
"""

fused_masked_fill_scale_relu_cpp_source = r"""
torch::Tensor fused_masked_fill_scale_relu_cuda(
    torch::Tensor att,
    torch::Tensor bias,
    float scale,
    int T
);
"""

# Compile the inline CUDA code for the fused operator
fused_masked_fill_scale_relu = load_inline(
    name="fused_masked_fill_scale_relu",
    cpp_sources=fused_masked_fill_scale_relu_cpp_source,
    cuda_sources=fused_masked_fill_scale_relu_source,
    extra_cflags=[""],
    extra_ldflags=[""],
    functions=["fused_masked_fill_scale_relu_cuda"],
    verbose=False
)

class NewGELU(nn.Module):
    def __init__(self):
        super(NewGELU, self).__init__()
    def forward(self, x):
        return 0.5 * x * (1.0 + torch.tanh(math.sqrt(2.0 / math.pi) * (x + 0.044715 * torch.pow(x, 3.0))))

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.register_buffer(
            "bias",
            torch.tril(torch.ones(max_seqlen, max_seqlen))
                 .view(1, 1, max_seqlen, max_seqlen)
        )
        self.n_head = n_head
        self.n_embd = n_embd
        self.max_seqlen = max_seqlen

    def forward(self, x):
        B, T, C = x.size()  # batch size, sequence length, embedding dim
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)

        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        # MatMul for attention scores
        att = torch.matmul(q, k.transpose(-2, -1))

        # Use our fused custom CUDA op for scaling, masked_fill, and ReLU
        att = fused_masked_fill_scale_relu.fused_masked_fill_scale_relu_cuda(
            att,
            self.bias[:, :, :T, :T],
            1.0 / math.sqrt(k.size(-1)),
            T
        )

        # Final matmul with v
        y = torch.matmul(att, v)
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        return y
